function val_cell($val) {
    if ($val === '-' || $val === '') {
        echo "<td class='p-2 text-center border-r text-slate-300 font-light'>-</td>";
    } elseif (strtolower($val) === 'blm ngaji') {
        echo "<td class='p-2 text-center border-r whitespace-nowrap'><span class='text-amber-700 font-medium bg-amber-50 rounded px-1.5 py-0.5 text-[10px] uppercase'>blm ngaji</span></td>";
    } else {
        echo "<td class='p-2 text-center border-r whitespace-nowrap'><span class='text-emerald-800 font-semibold bg-emerald-100/70 rounded px-1.5 py-0.5 text-[10px]'>{$val}</span></td>";
    }
}
?>
